/** Turn-size buckets, smallest first. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/** Exclusive upper bound of each bounded bucket; `huge` has none. */
const BELOW: readonly (readonly [Bucket, number])[] = [
	["tiny", 350],
	["small", 1800],
	["medium", 7000],
	["large", 24000],
];

/** The bucket a Turn of `tokens` estimated tokens falls in: lower bounds inclusive, upper exclusive. */
export function bucketOf(tokens: number): Bucket {
	for (const [bucket, below] of BELOW) if (tokens < below) return bucket;
	return "huge";
}

