import { describe, expect, test } from "bun:test";

import { bucketOf, weighted } from "./budget-table.ts";

describe("weighted", () => {
	test.each([
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	])("%p tokens weighs %p, by its bucket's weight at each boundary", (size, expected) => {
		expect(weighted([size])).toEqual([expected]);
	});

	test("keeps the order of the sizes and leaves results unrounded", () => {
		expect(weighted([8000, 120, 2400, 90, 30000])).toEqual([12000, 60, 3000, 45, 67500]);
		expect(weighted([1, 7]).map(String)).toEqual(["0.5", "3.5"]);
	});

	test("no sizes gives no weighted sizes", () => {
		expect(weighted([])).toEqual([]);
	});

	test("a negative size throws the same RangeError bucketOf throws", () => {
		expect(() => bucketOf(-1)).toThrow(RangeError);
		expect(() => weighted([120, -1])).toThrow(
			new RangeError("Turn size must be a finite, non-negative token count, got -1"),
		);
	});
});

