displayContent.text:
/** The plain sum of `sizes`, unweighted; 0 for no sizes. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/** Weight applied to a Turn's size by its bucket. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * Each of `sizes` times its bucket's weight, in the same order, rounded to the
 * nearest multiple of 10 with halves rounding up (365 → 370, 2252.5 → 2250).
 * Throws RangeError, from `bucketOf`, on a negative or non-finite size.
 */
export function weighted(sizes: number[]): number[] {
	// Sizes are non-negative, so Math.round's halves-toward-+∞ is halves-up.
	return sizes.map((size) => Math.round((size * WEIGHT[bucketOf(size)]) / 10) * 10);
}

/**
 * `n` as shown in a rendered table: below 1000 as is (`740`); from 1000 in
 * thousands with exactly one decimal and a `k` suffix, halves rounding up
 * (1234 → `1.2k`, 1250 → `1.3k`, 12000 → `12.0k`).
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	// Whole tenths of a thousand, so the decimal is built from integers rather
	// than left to toFixed's binary rounding; n is positive, so Math.round's
	// halves-toward-+∞ is halves-up.
	const tenths = Math.round(n / 100);
	return `${Math.floor(tenths / 10)}.${tenths % 10}k`;
}

/** Row label of each bucket in a rendered table. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/** The row label a rendered table shows for `bucket`. */
export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

