import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/** Columns of a rendered row are joined by this, unpadded. */
const SEPARATOR = " | ";

/**
 * The budget table for `sizes`, one string per row: the header
 * `bucket | turns | weighted`, then `<label> | <count> | <weighted total>` per
 * histogram entry in histogram order, the total shown through `formatCount`.
 * A bucket the histogram lists with no Turns shows a weighted total of 0.
 * Throws RangeError, from `bucketOf`, on a negative or non-finite size.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = histogram(sizes).map(({ bucket, count }) =>
		[labelOf(bucket), String(count), formatCount(totals.get(bucket) ?? 0)].join(SEPARATOR),
	);
	return [["bucket", "turns", "weighted"].join(SEPARATOR), ...rows];
}

