import { describe, expect, test } from "bun:test";

import {
	bucketOf,
	bucketTotals,
	formatCount,
	histogram,
	labelOf,
	totalOf,
	turnSizes,
} from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fractional size just under a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const leading: HarnessMessage = { role: "assistant", content: "Resuming from the earlier session." };
	const firstPrompt: HarnessMessage = { role: "user", content: "List the files." };
	const firstReply: HarnessMessage = { role: "assistant", content: "a.ts, b.ts" };
	const secondPrompt: HarnessMessage = { role: "user", content: "Now open a.ts and summarise it." };
	const secondReply: HarnessMessage = {
		role: "assistant",
		content: "It exports one function that tabulates Turn sizes against a Budget.",
	};
	const messages = [leading, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompt-led Turn and drops the messages before the first prompt", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("a leading user prompt with no text still forms a Turn", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([emptyPrompt, firstReply, secondPrompt, secondReply])).toEqual([
			approximateTokens([emptyPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("no user prompt at all yields no Turns", () => {
		expect(turnSizes([leading])).toEqual([]);
	});
});

describe("histogram", () => {
	test("counts per bucket, largest first, keeping empty buckets but leaving out an empty huge", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("huge leads the list once a size falls in it", () => {
		expect(histogram([24000, 30000, 10])).toEqual([
			{ bucket: "huge", count: 2 },
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("a size just under the huge bound leaves huge out and keeps an empty middle bucket", () => {
		expect(histogram([23999, 350, 349])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
