import { describe, expect, test } from "bun:test";

import {
	bucketOf,
	bucketTotals,
	formatCount,
	histogram,
	labelOf,
	summaryLine,
	totalOf,
	turnSizes,
} from "./budget-table.ts";
import { renderTable } from "./budget-render.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fractional size just under a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const leading: HarnessMessage = { role: "assistant", content: "Resuming from the earlier session." };
	const firstPrompt: HarnessMessage = { role: "user", content: "List the files." };
	const firstReply: HarnessMessage = { role: "assistant", content: "a.ts, b.ts" };
	const secondPrompt: HarnessMessage = { role: "user", content: "Now open a.ts and summarise it." };
	const secondReply: HarnessMessage = {
		role: "assistant",
		content: "It exports one function that tabulates Turn sizes against a Budget.",
	};
	const messages = [leading, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompt-led Turn and drops the messages before the first prompt", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("a leading user prompt with no text still forms a Turn", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([emptyPrompt, firstReply, secondPrompt, secondReply])).toEqual([
			approximateTokens([emptyPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("no user prompt at all yields no Turns", () => {
		expect(turnSizes([leading])).toEqual([]);
	});
});

describe("histogram", () => {
	test("counts per bucket, largest first, keeping empty buckets but leaving out an empty huge", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("huge leads the list once a size falls in it", () => {
		expect(histogram([24000, 30000, 10])).toEqual([
			{ bucket: "huge", count: 2 },
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("a size just under the huge bound leaves huge out and keeps an empty middle bucket", () => {
		expect(histogram([23999, 350, 349])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("no sizes gives every bucket but huge at zero", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});

	test("a negative size throws RangeError", () => {
		expect(() => histogram([120, -1])).toThrow(RangeError);
	});
});

describe("totalOf", () => {
	test("sums the sizes unweighted", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
	});

	test("no sizes totals zero", () => {
		expect(totalOf([])).toBe(0);
	});
});

describe("bucketTotals", () => {
	test("sums each Turn's rounded weighted size per occupied bucket, smallest bucket first", () => {
		// 90 weighs 45, rounded to 50, so tiny is 50 + 60 + 50 = 160, not 150.
		expect([...bucketTotals([8000, 90, 120, 2400, 90, 400])]).toEqual([
			["tiny", 160],
			["small", 400],
			["medium", 3000],
			["large", 12000],
		]);
	});

	test("no sizes gives no entries", () => {
		expect(bucketTotals([]).size).toBe(0);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1249, "1.2k"],
		[1250, "1.3k"],
		[1150, "1.2k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
	])("%p shows as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	test.each([
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	] as const)("%p is labelled %p", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});
});

describe("renderTable", () => {
	test("a header, then one row per histogram entry, largest bucket first, totals via formatCount", () => {
		// tiny: 90 → 50, 120 → 60, 90 → 50, summed per Turn to 160.
		expect(renderTable([8000, 90, 120, 2400, 90, 400])).toEqual([
			"bucket | turns | weighted",
			"feasts | 1 | 12.0k",
			"meals | 1 | 3.0k",
			"bites | 1 | 400",
			"crumbs | 3 | 160",
		]);
	});

	test("a huge Turn adds a banquets row; buckets with no Turns total 0", () => {
		expect(renderTable([30000])).toEqual([
			"bucket | turns | weighted",
			"banquets | 1 | 67.5k",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("no sizes still shows every bucket but banquets", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("a negative size throws RangeError", () => {
		expect(() => renderTable([120, -1])).toThrow(RangeError);
	});
});

describe("summaryLine", () => {
	test("matches the documented example", () => {
		expect(summaryLine([7000, 2000, 400], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("over counts only sizes strictly above 9000; used rounds down and may exceed 100", () => {
		expect(summaryLine([9000, 9001, 30000], 1000)).toBe(
			"turns=3 · total=48001 · used=4800% · peak=huge · over=2",
		);
	});

	test("no sizes shows peak=none", () => {
		expect(summaryLine([], 1000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("a negative size throws RangeError", () => {
		expect(() => summaryLine([120, -1], 1000)).toThrow(RangeError);
	});
});

